use super::*;
#[test]
fn original_history_identity_matches_controlled_reference_and_independent_wide_fixture(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../🪪️checkpoint-identity/🎟️original/fixture.json")).unwrap();let edits=vec![f["pattern"].as_str().unwrap().repeat(f["repeat"].as_u64().unwrap()as usize),"edit-2".into()];let checkpoints=vec![format!("ck-{}",&f["digest"].as_str().unwrap()[..16])];let name="Alternative λ\n";let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:1};
 for input in [OriginalHistoryIdentityInput::Change{edit_ids:&edits,description:None},OriginalHistoryIdentityInput::Alternative{name,checkpoint_id:&checkpoints[0]}]{for cut in [Some(0),Some(1),Some(13),None]{let mut owner=OriginalHistoryIdentity::default();for step in 0..100000{if cut==Some(step)||owner.digest().is_some(){break}let d=owner.demands();assert!(d.copy_bytes<=4096);for axis in [0,1,4]{let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,_=>denied.maximum_depth=0};let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(31,&input,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(31,&input,grant).unwrap());assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(step<99999);}if cut.is_none(){let digest=owner.digest().unwrap();let mut accept=|_|true;let mut control=NativeEncodeControl::new(4096,&mut accept);let(prefix,_,_,_)=input.parts();let printed=print_identity_digest(prefix,&digest,&mut control).unwrap();let reference=match &input{OriginalHistoryIdentityInput::Change{edit_ids,description}=>mint_change_id(edit_ids,*description,&mut control).unwrap(),OriginalHistoryIdentityInput::Alternative{name,..}=>mint_alternative_id(name,&checkpoints,&mut control).unwrap()};assert_eq!(printed,reference);assert_eq!(printed,f[if prefix=="change"{"changeIdentity"}else{"alternativeIdentity"}].as_str().unwrap());}if !owner.terminal_is_empty(){assert!(owner.advance(32,&input,grant).is_err());}assert!(owner.close_step(grant).fits(grant));assert!(owner.terminal_is_empty());}}
}
